using EEMS.Modules.Inventory.Domain;using Microsoft.EntityFrameworkCore;
namespace EEMS.Modules.Inventory.Infrastructure;
public sealed class InventoryDbContext(DbContextOptions<InventoryDbContext> options):DbContext(options){public DbSet<MovementType> MovementTypes=>Set<MovementType>();public DbSet<AllocationState> AllocationStates=>Set<AllocationState>();public DbSet<InventoryItem> Items=>Set<InventoryItem>();public DbSet<Warehouse> Warehouses=>Set<Warehouse>();public DbSet<StockMovement> Movements=>Set<StockMovement>();public DbSet<StockAllocation> Allocations=>Set<StockAllocation>();
protected override void OnModelCreating(ModelBuilder modelBuilder){modelBuilder.HasDefaultSchema("inventory");
var t=modelBuilder.Entity<MovementType>();t.ToTable("movement_types");t.HasKey(x=>x.Id);t.Property(x=>x.Id).HasColumnName("movement_type_id").ValueGeneratedNever();t.Property(x=>x.Code).HasColumnName("code").HasMaxLength(40);t.Property(x=>x.Name).HasColumnName("name").HasMaxLength(100);t.Property(x=>x.RequiresSource).HasColumnName("requires_source");t.Property(x=>x.RequiresDestination).HasColumnName("requires_destination");t.Property(x=>x.IsActive).HasColumnName("is_active");t.HasIndex(x=>x.Code).IsUnique();
var s=modelBuilder.Entity<AllocationState>();s.ToTable("allocation_states");s.HasKey(x=>x.Id);s.Property(x=>x.Id).HasColumnName("allocation_state_id").ValueGeneratedNever();s.Property(x=>x.Code).HasColumnName("code").HasMaxLength(40);s.Property(x=>x.Name).HasColumnName("name").HasMaxLength(100);s.Property(x=>x.IsTerminal).HasColumnName("is_terminal");s.Property(x=>x.IsActive).HasColumnName("is_active");s.HasIndex(x=>x.Code).IsUnique();
var i=modelBuilder.Entity<InventoryItem>();i.ToTable("items");i.HasKey(x=>x.Id);i.Property(x=>x.Id).HasColumnName("item_id");i.Property(x=>x.TenantId).HasColumnName("tenant_id");i.Property(x=>x.Sku).HasColumnName("sku").HasMaxLength(80);i.Property(x=>x.Name).HasColumnName("name").HasMaxLength(180);i.Property(x=>x.Unit).HasColumnName("unit").HasMaxLength(40);i.Property(x=>x.IsActive).HasColumnName("is_active");i.HasIndex(x=>new{x.TenantId,x.Id}).IsUnique();i.HasIndex(x=>new{x.TenantId,x.Sku}).IsUnique();
var w=modelBuilder.Entity<Warehouse>();w.ToTable("warehouses");w.HasKey(x=>x.Id);w.Property(x=>x.Id).HasColumnName("warehouse_id");w.Property(x=>x.TenantId).HasColumnName("tenant_id");w.Property(x=>x.AreaId).HasColumnName("area_id");w.Property(x=>x.Name).HasColumnName("name").HasMaxLength(160);w.Property(x=>x.IsActive).HasColumnName("is_active");w.HasIndex(x=>new{x.TenantId,x.Id}).IsUnique();w.HasIndex(x=>new{x.TenantId,x.AreaId,x.Name}).IsUnique();
var m=modelBuilder.Entity<StockMovement>();m.ToTable("stock_movements");m.HasKey(x=>x.Id);m.Property(x=>x.Id).HasColumnName("movement_id");m.Property(x=>x.TenantId).HasColumnName("tenant_id");m.Property(x=>x.ItemId).HasColumnName("item_id");m.Property(x=>x.MovementTypeId).HasColumnName("movement_type_id");m.Property(x=>x.SourceWarehouseId).HasColumnName("source_warehouse_id");m.Property(x=>x.DestinationWarehouseId).HasColumnName("destination_warehouse_id");m.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");m.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,3);m.Property(x=>x.Reference).HasColumnName("reference").HasMaxLength(120);m.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at");m.HasOne<MovementType>().WithMany().HasForeignKey(x=>x.MovementTypeId).OnDelete(DeleteBehavior.Restrict);m.HasIndex(x=>new{x.TenantId,x.ItemId,x.OccurredAtUtc});m.HasIndex(x=>new{x.TenantId,x.Reference}).IsUnique();
var a=modelBuilder.Entity<StockAllocation>();a.ToTable("allocations");a.HasKey(x=>x.Id);a.Property(x=>x.Id).HasColumnName("allocation_id");a.Property(x=>x.TenantId).HasColumnName("tenant_id");a.Property(x=>x.ElectionId).HasColumnName("election_id");a.Property(x=>x.ItemId).HasColumnName("item_id");a.Property(x=>x.SourceWarehouseId).HasColumnName("source_warehouse_id");a.Property(x=>x.TeamId).HasColumnName("team_id");a.Property(x=>x.PollingCenterId).HasColumnName("polling_center_id");a.Property(x=>x.RecipientUserId).HasColumnName("recipient_user_id");a.Property(x=>x.StateId).HasColumnName("allocation_state_id");a.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,3);a.Property(x=>x.CreatedAtUtc).HasColumnName("created_at");a.Property(x=>x.AcknowledgedAtUtc).HasColumnName("acknowledged_at");a.HasOne<AllocationState>().WithMany().HasForeignKey(x=>x.StateId).OnDelete(DeleteBehavior.Restrict);a.HasIndex(x=>new{x.TenantId,x.ElectionId,x.StateId});}}
